import{_ as a,o,c as s,ag as t}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Permissões","description":"","frontmatter":{},"headers":[],"relativePath":"pt/nay-lib/permissions.md","filePath":"pt/nay-lib/permissions.md"}'),d={name:"pt/nay-lib/permissions.md"};function r(i,e,n,c,p,l){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="permissoes" tabindex="-1">Permissões <a class="header-anchor" href="#permissoes" aria-label="Permalink to &quot;Permissões&quot;">​</a></h1><p>Cada ação Nayretis que exige direitos verifica um <strong>âmbito</strong>. Os âmbitos concedem-se por ACE, por regras guardadas na base de dados ou no separador Permissões do <code>/nay</code>.</p><h2 id="ambitos" tabindex="-1">Âmbitos <a class="header-anchor" href="#ambitos" aria-label="Permalink to &quot;Âmbitos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Âmbito</th><th>Concede</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Tudo: todos os scripts, as definições Nayretis, as permissões, os tokens de API, os webhooks e o registo.</td></tr><tr><td><code>nay.config</code></td><td>As definições de todos os scripts.</td></tr><tr><td><code>nay.audit</code></td><td>O registo.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>As definições de um script, por exemplo <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>Uma permissão declarada por um script, listada na respetiva página.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Todos os âmbitos de um script. Funciona com regras (<code>nay_grant</code>), não com ACE.</td></tr></tbody></table><h2 id="por-ace" tabindex="-1">Por ACE <a class="header-anchor" href="#por-ace" aria-label="Permalink to &quot;Por ACE&quot;">​</a></h2><p>Um ACE sobre um âmbito concede esse âmbito. Conceda cada âmbito pelo nome completo (os âmbitos com caracteres universais, como <code>nay_car_wash.*</code>, só funcionam como regras). No <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="por-regras" tabindex="-1">Por regras <a class="header-anchor" href="#por-regras" aria-label="Permalink to &quot;Por regras&quot;">​</a></h2><p>As regras ficam guardadas na base de dados e podem visar diretamente um jogador. Uma regra tem um tipo, um identificador e um âmbito. Os tipos são:</p><ul><li><code>ace</code>: todos os jogadores autorizados nesse objeto ACE;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code>: um jogador, pelo identificador.</li></ul><p>A partir da consola do servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> e <code>nay_revoke</code> recebem <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> lista todas as regras com o número de cada uma.</p><p>No jogo, o separador <strong>Permissões</strong> do <code>/nay</code> (âmbito <code>nay.admin</code>) lista, adiciona e remove estas mesmas regras. Cada alteração fica gravada no <a href="/pt/nay-lib/audit">registo</a>.</p>`,14)])])}const u=a(d,[["render",r]]);export{g as __pageData,u as default};
